1	export type Cell = [number, number];
2	
3	const NEIGHBOR_OFFSETS: ReadonlyArray<Cell> = [
4	  [-1, -1], [-1, 0], [-1, 1],
5	  [ 0, -1],          [ 0, 1],
6	  [ 1, -1], [ 1, 0], [ 1, 1],
7	];
8	
9	const cellKey = ([x, y]: Cell): string => `${x},${y}`;
10	
11	const survivesWithNeighborCount = (count: number): boolean =>
12	  count === 2 || count === 3;
13	
14	const isBornWithNeighborCount = (count: number): boolean => count === 3;
15	
16	const neighborsOf = ([x, y]: Cell): Cell[] =>
17	  NEIGHBOR_OFFSETS.map(([dx, dy]) => [x + dx, y + dy]);
18	
19	export function nextGeneration(cells: Cell[]): Cell[] {
20	  const alive = new Set(cells.map(cellKey));
21	  const countAliveNeighbors = (cell: Cell): number =>
22	    neighborsOf(cell).filter((n) => alive.has(cellKey(n))).length;
23	
24	  const survivors = cells.filter((cell) =>
25	    survivesWithNeighborCount(countAliveNeighbors(cell)),
26	  );
27	
28	  const deadNeighbors = new Map<string, Cell>(
29	    cells
30	      .flatMap(neighborsOf)
31	      .filter((n) => !alive.has(cellKey(n)))
32	      .map((n) => [cellKey(n), n]),
33	  );
34	  const births = [...deadNeighbors.values()].filter((n) =>
35	    isBornWithNeighborCount(countAliveNeighbors(n)),
36	  );
37	
38	  return [...survivors, ...births];
39	}
