export function nextGeneration(cells: Cell[]): Cell[] {
  const alive = new Set(cells.map(cellKey));
  const countAliveNeighbors = (cell: Cell): number =>
    neighborsOf(cell).filter((n) => alive.has(cellKey(n))).length;

  const survivors = cells.filter((cell) =>
    survivesWithNeighborCount(countAliveNeighbors(cell)),
  );

  const deadNeighbors = new Map<string, Cell>(
    cells
      .flatMap(neighborsOf)
      .filter((n) => !alive.has(cellKey(n)))
      .map((n) => [cellKey(n), n]),
  );
  const births = [...deadNeighbors.values()].filter((n) =>
    isBornWithNeighborCount(countAliveNeighbors(n)),
  );

  return [...survivors, ...births];
}

